export function i2cCSV(transactions){return 'start_cycle,end_cycle,time_ms,address,frequency_hz,direction,address_ack,data_ack,byte_count,data_hex\n'+transactions.map(t=>[t.cycle,t.end,(t.cycle/16000).toFixed(6),'0x'+t.address.toString(16).toUpperCase().padStart(2,'0'),t.frequency,t.write?'W':'R',Number(t.ack),Number(t.dataACK),t.byteCount,t.data.map(b=>b.toString(16).toUpperCase().padStart(2,'0')).join(' ')].join(',')).join('\n')+'\n';}
